import math

nu = 1.08e-5 # ft2/s
g = 32.174 # ft/s2

def colebrook(e, D, Re):
    if Re < 2000:
        return 64.0 / Re
    f = 0.02
    for _ in range(50):
        val = -2.0 * math.log10((e / D) / 3.7 + 2.51 / (Re * math.sqrt(f)))
        f_new = 1.0 / (val ** 2)
        if abs(f_new - f) < 1e-9:
            break
        f = f_new
    return f

def skid_head_avail(skid_type, Q_skid):
    # piecewise linear interpolation
    if skid_type == 'FS-600':
        pts = [(0, 182), (150, 176), (300, 163), (450, 141), (600, 106), (700, 74)]
    else: # FS-1200
        pts = [(0, 212), (300, 204), (600, 188), (900, 159), (1200, 117), (1400, 82)]
    if Q_skid < 0 or Q_skid > pts[-1][0]:
        return None # Beyond curve
    for i in range(len(pts)-1):
        q0, h0 = pts[i]
        q1, h1 = pts[i+1]
        if q0 <= Q_skid <= q1:
            return h0 + (h1 - h0) * (Q_skid - q0) / (q1 - q0)
    return None

print('FS-600 at 300 gpm:', skid_head_avail('FS-600', 300))
print('FS-1200 at 1200 gpm:', skid_head_avail('FS-1200', 1200))
"

